import{z as l,x as A,o as E,c as B,q as e,j as r,D as t,d as n,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"QLIKE 与波动预测评估","description":"","frontmatter":{"title":"QLIKE 与波动预测评估","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/qlike-vol-forecast-eval.md","filePath":"quant/qlike-vol-forecast-eval.md","lastUpdated":1791063341000}'),h={name:"quant/qlike-vol-forecast-eval.md"};function p(d,a,_,c,m,C){const o=A("Mermaid");return E(),B("div",null,[a[2]||(a[2]=e('<h1 id="qlike-与波动预测评估" tabindex="-1">QLIKE 与波动预测评估 <a class="header-anchor" href="#qlike-与波动预测评估" aria-label="Permalink to &quot;QLIKE 与波动预测评估&quot;">​</a></h1><div class="epigraph"><p>用带噪声的已实现量去比较波动预测时，大多数损失函数会把更差的模型判成更好；少数损失——包括 QLIKE——在代理无偏时仍能排出正确的顺序。</p><footer>—— Patton, Volatility Forecast Comparison Using Imperfect Volatility Proxies, Journal of Econometrics, 2011</footer></div><p><a href="/quant/arfima-long-memory">ARFIMA</a> 与 <a href="/quant/har-rv">HAR</a>、<a href="/quant/garch">GARCH</a> 都会给出 \\(\\hat\\sigma_{t+1}^2\\)。样本内 \\(R^2\\)、对 RV 的 MSE，在 RV 只是积分波动的带噪代理时，<strong>可以选错模型</strong>。Patton 刻画：哪些损失对代理噪声稳健（仍一致地选出真条件方差）。QLIKE \\(L(h,x)=x/h-\\log(x/h)-1\\)（\\(h\\) 预测，\\(x\\) 代理）属于此列。本课缺口：比较波动模型必须换正当损失，并用 Diebold–Mariano / <a href="/quant/hansen-spa">Hansen SPA</a> 做样本外推断。下一课把一元方差变成多元 BEKK，评估仍用这里的损失纪律。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>真对象是 \\(E[r_{t+1}^2\\mid\\mathcal{F}_t]\\) 或 \\(IV_{t+1}\\)。观测到的是 \\(RV_{t+1}\\) 或 \\(r_{t+1}^2\\)。MSE \\(E[(RV-\\hat h)^2]\\) 在 \\(RV=IV+\\eta\\)、\\(\\eta\\) 与模型相关时，可以偏向于拟合噪声的模型。Patton 给出充分条件：损失必须让「对真 \\(h_0\\) 的期望损失」在代理无偏时仍最小化于 \\(h_0\\)。QLIKE 与归一化 MSE 一类满足；对 \\(\\sqrt{RV}\\) 的 MAE 往往不满足。</p><p><span class="marginnote">数字实例：预测 \\(h=1\\%\\)、代理 \\(x=2\\%\\) 时，QLIKE 为 \\(2-\\ln 2-1\\approx0.31\\)；反过来预测 2%、实际 1%，损失约 \\(0.5-\\ln 0.5-1\\approx0.19\\)。同样「差 1 个点」，低估波动挨的打更重——这正是风控想要的非对称。</span></p><p>问题是：固定代理（哪一种 RV）、固定损失、固定样本外窗口，再比较。对象不是「谁 \\(R^2\\) 高」，而是<strong>条件期望的评分规则</strong>。</p><h3 id="代理选择" tabindex="-1">代理选择 <a class="header-anchor" href="#代理选择" aria-label="Permalink to &quot;代理选择&quot;">​</a></h3><p>日收益平方噪声极大，排序功效低。五分钟 RV、TSRV、已实现核更好，但仍有偏差，见 <a href="/quant/rv-noise">rv-noise</a>。代理有偏（噪声未减）时，连 QLIKE 的稳健性也要打折——Patton 的定理要求代理对 \\(IV\\) 无偏或偏差与 \\(h\\) 无关。隔夜是否并入须两边一致。</p><p><span class="marginnote">对 \\(\\log RV\\) 做 MSE 再指数化，比较的是对数域，不是 QLIKE 的对象。变换必须写进损失。HAR 估对数、GARCH 估水平，不能直接比 \\(R^2\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>QLIKE。</strong> 对每个 \\(t\\)，用 \\(\\hat h_t\\) 与 \\(RV_t\\) 算损失，样本外平均。数值上 \\(\\hat h_t\\gt 0\\) 强制，GARCH 要检查。QLIKE 重罚低估波动（\\(x/h\\) 大），对风控比对称 MSE 更对口。</p><p><span class="marginnote">术语翻译：「正当损失」（proper loss）可以读成「诚实评分」——只有报出真实条件方差，期望得分才最高，报偏了一定更差。QLIKE 的特殊之处是：即使打分用的实际波动是带噪代理，这个性质仍然保留。</span></p><p><strong>推断。</strong> Diebold–Mariano 对损失差做 t，HAC 滞后与重叠地平线匹配。嵌套模型（GARCH 对常数方差）DM 的零分布非标准，应用 Clark–West 或自助。多模型用 Hansen SPA 或 Romano–Wolf，避免「扫十个 HAR 变体再报最佳」。</p><p><strong>校准。</strong> Mincer–Zarnowitz：\\(RV_{t+1}=a+b\\hat h_{t+1}+e\\)，无偏要 \\(a=0,b=1\\)，标准误 HAC。\\(b\\lt 1\\) 常见于噪声代理导致的衰减，不一定是预测有偏——又一个 Patton 警告。应同时看 QLIKE 与 MZ，不单看 \\(R^2\\)。</p><h3 id="与-var-回测分工" tabindex="-1">与 VaR 回测分工 <a class="header-anchor" href="#与-var-回测分工" aria-label="Permalink to &quot;与 VaR 回测分工&quot;">​</a></h3><p>QLIKE 评的是整个条件方差，不是单分位。VaR 命中率可以过、方差预测仍差（尾部形状补偿）。风控应两套都报。CAViaR 用分位损失，不是 QLIKE。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>评分规则严格正当：真条件期望唯一最小化期望损失。QLIKE 来自高斯似然（忽略常数）对方差的部分，故对条件方差正当。代理 \\(x=h_0+\\eta\\)，\\(E[\\eta\\mid h_0]=0\\) 时，期望 QLIKE 仍在 \\(h=h_0\\) 最小——噪声平均掉。MSE 对 \\(x\\) 正当，对 \\(h_0\\) 在异方差噪声下不必。这就是「不完美代理」论文的机制。</p>',19)),(E(),r(i,null,{default:t(()=>[s(o,{id:"mermaid-55",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E4%BB%A3%E7%90%86%20x%20%3D%20h0%20%2B%20%CE%B7%EF%BC%88%E5%B8%A6%E5%99%AA%20RV%EF%BC%89%22%5D%20--%3E%20Q%5B%22%E6%9C%9F%E6%9C%9B%20QLIKE%22%5D%0A%20%20X%20--%3E%20M%5B%22%E6%9C%9F%E6%9C%9B%20MSE%EF%BC%88%E5%AF%B9%20x%EF%BC%89%22%5D%0A%20%20Q%20--%3E%7C%22%CE%B7%20%E6%9D%A1%E4%BB%B6%E5%9D%87%E5%80%BC%E4%B8%BA%E9%9B%B6%22%7C%20MIN%5B%22%E4%BB%8D%E5%9C%A8%E7%9C%9F%E5%80%BC%20h0%20%E5%A4%84%E6%9C%80%E5%B0%8F%EF%BC%9A%E6%8E%92%E5%BA%8F%E7%A8%B3%E5%81%A5%22%5D%0A%20%20M%20--%3E%7C%22%CE%B7%20%E4%B8%8E%E6%A8%A1%E5%9E%8B%E7%9B%B8%E5%85%B3%E6%97%B6%22%7C%20BIAS%5B%22%E6%9C%80%E4%BC%98%E7%82%B9%E5%81%8F%E7%A6%BB%20h0%EF%BC%9A%E5%8F%AF%E8%83%BD%E5%81%8F%E7%88%B1%E6%8B%9F%E5%90%88%E5%99%AA%E5%A3%B0%E7%9A%84%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20MIN%20--%3E%20USE%5B%22%E5%8F%AF%E4%BD%9C%E4%B8%BA%E9%80%89%E6%A8%A1%E4%BE%9D%E6%8D%AE%22%5D%0A%20%20BIAS%20--%3E%20REF%5B%22%E5%8F%AA%E8%83%BD%E4%BD%9C%E5%AF%B9%E7%85%A7%EF%BC%8C%E4%B8%8D%E5%BD%93%E9%80%89%E6%A8%A1%E4%BE%9D%E6%8D%AE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<p><span class="marginnote">常见误区：用样本内 \\(R^2\\) 或对 RV 的 MSE 排名，就以为选出了「最好的波动模型」。噪声代理下，MSE 可能给「把噪声也拟合进去」的模型发奖；正确姿势是 QLIKE 加样本外 DM/SPA 检验。</span></p><p>样本外必须时间序列切：滚动或固定训练–测试，禁止打乱。这与 <a href="/quant/bootstrap-finance">bootstrap</a> 的块原子、与标签重叠课同一纪律。</p><p><span class="marginnote">多步波动预测（周、月）把 HAR 的周月成分派上用场。损失应对齐地平线：用周 RV 评周预测，不要用日 QLIKE 加总假装评了周。</span></p><h3 id="到多元的交接" tabindex="-1">到多元的交接 <a class="header-anchor" href="#到多元的交接" aria-label="Permalink to &quot;到多元的交接&quot;">​</a></h3><p>一元 QLIKE 有多元推广（Frobenius 对协方差、或 Wishart/QLIKE 型）。下一课 BEKK 产出完整 \\(H_t\\)，应用协方差损失，而不是只比对角线。先一元纪律，再多元参数爆炸。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>跳跃日 RV 极大，QLIKE 会被几天主导——可并列跳跃稳健 BV 作代理，或对损失 winsor，并声明对象是否含跳。模型在危机切换后全样本赢家可能是「危机专用」，应分段评，接 Chow。</p><p>工程：默认代理 = 预登记的 RV；损失 = QLIKE + MSE 对照；推断 = DM/HAC 或 SPA。不要用样本内似然选生产模型。不要对 tick 平方做 QLIKE 当高频预测评估——代理定义将在高频单元重写，见最后一课 <a href="/quant/hf-forecast-loss">高频预测损失</a>。</p>',8)),(E(),r(i,null,{default:t(()=>[s(o,{id:"mermaid-80",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22GARCH%20%2F%20HAR%20%2F%20ARFIMA%22%5D%20--%3E%20H%5B%22%E9%A2%84%E6%B5%8B%20h_t%22%5D%0A%20%20RV%5B%22%E4%BB%A3%E7%90%86%20RV%22%5D%20--%3E%20L%5B%22%E6%8D%9F%E5%A4%B1%3A%20QLIKE%20%E6%AD%A3%E5%BD%93%22%5D%0A%20%20H%20--%3E%20L%0A%20%20L%20--%3E%20DM%5B%22DM%20%2F%20SPA%20%E6%A0%B7%E6%9C%AC%E5%A4%96%22%5D%0A%20%20MSE%5B%22%E5%AF%B9%20RV%20%E7%9A%84%20MSE%22%5D%20--%3E%20WARN%5B%22%E5%8F%AF%E4%B8%8D%E4%B8%80%E8%87%B4%E9%80%89%E5%87%BA%E7%9C%9F%20h%22%5D%0A%20%20RV%20--%3E%20MZ%5B%22Mincer-Zarnowitz%20%E6%A0%A1%E5%87%86%22%5D%0A%20%20H%20--%3E%20MZ%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>用不完美 RV 比较波动预测时，应用 Patton 意义下稳健的损失，QLIKE 是默认。</li><li>代理须尽量无偏（噪声修正、隔夜定义一致）；样本外用 DM/SPA，嵌套须校正。</li><li>MZ 回归的 \\(R^2\\) 与 \\(b\\) 受代理噪声衰减，不能单独当选模依据。</li><li>跳跃、断点、地平线错配会让单一赢家没有对象。</li><li>出处：Patton, <em>Journal of Econometrics</em>, 2011；Diebold and Mariano, <em>Journal of Business &amp; Economic Statistics</em>, 1995；Hansen SPA 见 Hansen, 2005。</li></ul>',2))])}const u=l(h,[["render",p]]);export{D as __pageData,u as default};
